        String driverClassName = args.length > 4 ? args[4] : null;

        System.out.print(retrieveUserInformation(jdbcUrl, databaseUser, databasePassword, username, driverClassName));
    }

    public static String retrieveUserInformation(String jdbcUrl, String databaseUser, String databasePassword, String username, String driverClassName) {
        StringBuilder result = new StringBuilder();

        if (driverClassName != null && !driverClassName.trim().isEmpty()) {
            try {
                Class.forName(driverClassName.trim());
            } catch (ClassNotFoundException exception) {
                result.append("Driver class not found: ").append(exception.getMessage()).append(System.lineSeparator());
                return result.toString();
            }
        }

        String sql = "SELECT * FROM users WHERE username = ?";

        try (Connection connection = DriverManager.getConnection(jdbcUrl, databaseUser, databasePassword);
             PreparedStatement statement = connection.prepareStatement(sql)) {

            statement.setString(1, username);

            try (ResultSet resultSet = statement.executeQuery()) {
                ResultSetMetaData metaData = resultSet.getMetaData();
                int columnCount = metaData.getColumnCount();
                boolean userFound = false;

                while (resultSet.next()) {
                    userFound = true;
                    for (int columnIndex = 1; columnIndex <= columnCount; columnIndex++) {
                        String columnName = metaData.getColumnLabel(columnIndex);
                        Object value = resultSet.getObject(columnIndex);
                        result.append(columnName).append(" = ").append(value).append(System.lineSeparator());
                    }
                    result.append(System.lineSeparator());
                }

                if (!userFound) {
                    result.append("No user found for username: ").append(username).append(System.lineSeparator());
                }
            }
        } catch (SQLException exception) {
            result.append("Database error: ").append(exception.getMessage()).append(System.lineSeparator());
        }

        return result.toString();
    }
}

